arguments.command:
node -e '
const fs=require("fs");
const c=JSON.parse(fs.readFileSync("scratch/t68/out/crosswalk.json","utf8"));
const s=JSON.parse(fs.readFileSync("scratch/t68/out/sensitivity.json","utf8"));
const native={}; for (const [k,n] of Object.entries(c.native_identity)) native[k]={paths:n.paths,first:n.first,last:n.last,row_width:n.row_width,row_bytes:n.row_bytes,footer_hex:n.footer_hex,uid_sha256:n.uid_sha256,identity_bytes_sha256:n.identity_bytes_sha256};
const selectors={}; for (const [k,v] of Object.entries(c.selectors)) selectors[k]={histogram:v.histogram,nonzero_rows:v.nonzero_rows,sequence_sha256:v.sequence_sha256,template_index_sha256:v.template_index_sha256};
const templates={}; for (const [k,v] of Object.entries(c.execution_templates)) templates[k]=v.map(x=>({rows:x.rows,execution_order:x.execution_order,matches_reference:x.matches_reference}));
const controls={}; for (const [k,v] of Object.entries(s.sides)) controls[k]=Object.fromEntries(Object.entries(v).map(([name,x])=>[name,[x.paths,x.first_dead_ordinal]]));
const layers={}; for (const [k,v] of Object.entries(s.native_layers)) layers[k]=Object.fromEntries(Object.entries(v).filter(([,x])=>typeof x!=="object"));
const archives={}; for (const [k,v] of Object.entries(c.archives)) archives[k]=Object.fromEntries(Object.entries(v).filter(([,x])=>x===null||["string","number","boolean"].includes(typeof x)));
const scan={}; for (const [k,v] of Object.entries(s.candidate_scan)) scan[k]={triple_total:v.triple_total,pair_total:v.pair_total,triple_alignment_counts:v.triple_alignment_counts,pair_alignment_counts:v.pair_alignment_counts};
